import re
from decimal import Decimal, ROUND_HALF_UP

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"(\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"\s*" + _NUM + r"\s*([A-Za-z]+)")
_BARE_INT = re.compile(r"\d+")
_CLOCK = re.compile(r"\d+(?::\d+){1,2}")
_ISO = re.compile(
    r"P"
    r"(?:" + _NUM + r"W)?"
    r"(?:" + _NUM + r"D)?"
    r"(?:T"
    r"(?:" + _NUM + r"H)?"
    r"(?:" + _NUM + r"M)?"
    r"(?:" + _NUM + r"S)?"
    r")?",
    re.IGNORECASE,
)
_ISO_UNITS = (604800, 86400, 3600, 60, 1)


def _to_seconds(total) -> int:
    return int((Decimal(total)).quantize(Decimal(1), rounding=ROUND_HALF_UP))


def _parse_iso(text: str) -> int:
    m = _ISO.fullmatch(text)
    if not m or text.upper() in ("P", "PT") or text.upper().endswith("T"):
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    total = Decimal(0)
    for value, mult in zip(m.groups(), _ISO_UNITS):
        if value is not None:
            total += Decimal(value) * mult
    return _to_seconds(total)


def _parse_clock(text: str) -> int:
    if not _CLOCK.fullmatch(text):
        raise ValueError(f"invalid clock duration: {text!r}")
    fields = [int(f) for f in text.split(":")]
    if any(f >= 60 for f in fields[1:]):
        raise ValueError(f"invalid clock duration: {text!r}")
    total = 0
    for f in fields:
        total = total * 60 + f
    return total


def _parse_components(text: str) -> int:
    total = Decimal(0)
    pos = 0
    n = len(text)
    while pos < n:
        if text[pos].isspace():
            pos += 1
            continue
        m = _COMPONENT.match(text, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += Decimal(m.group(1)) * _UNITS[unit]
        pos = m.end()
    return _to_seconds(total)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")
    if s[0] in "Pp":
        return _parse_iso(s)
    if ":" in s:
        return _parse_clock(s)
    if _BARE_INT.fullmatch(s):
        return int(s)
    return _parse_components(s)

